export const CHAPEL_OBJECTIVES={chapter_complete:'Поговорите с Джоном о колоколе',chapel_travel:'Пройдите к часовне за южным краем кладбища',chapel_echoes:'Разрушьте три оберега колокола',chapel_choice:'Остановите колокол',chapel_ghost:'Победите призрака звонаря у входа в часовню',chapel_ectoplasm:'Подберите останки звонаря',chapel_return:'Отнесите останки звонаря Джону',chapel_witness:'Поговорите с призраком звонаря у Джона',chapel_done:'Поговорите с Джоном о звонаре',kingdom_letter:'Поговорите с Альфредом о помощи королевства',kingdom_road:'Выйдите на Королевский тракт через северные ворота деревни'};
export const chapelUnlocked=p=>p.stage.startsWith('chapel_')||p.stage.startsWith('kingdom_')||p.rewards.includes('chapel-quest');
const WARDS=[
 'В камень вбиты ржавые гвозди и звериные зубы. От оберега тянется тонкий звон. Когда вы ломаете его, на миг стихает даже ветер.',
 'Оберег связан из человеческих костей. На верёвке тот же узел, что был у слуг Лича. Вы разрываете его; колокол сбивается с ритма.',
 'Под алтарём спрятан последний оберег. На его краю засохла кровь. После удара по камню звон становится тише — теперь можно добраться до колокола.'];
export function chapelQuest({p,world,slots=[],show,close,sync,sound,reward,owned=id=>slots.filter(i=>i?.id===id).reduce((n,i)=>n+i.count,0),take=id=>{const i=slots.findIndex(s=>s?.id===id);if(i<0)return false;if(!--slots[i].count)slots[i]=null;return true},summon=()=>{},dismiss=()=>{}}){
 function tick(){if(!world)return;if(p.stage==='chapel_choice'&&world.choice){p.stage='chapel_ghost';sync()}if(['chapel_return','chapel_done'].includes(p.stage)&&world.ghostSpawned&&!world.ghostDefeated){p.stage='chapel_ghost';sync()}if(world.inside&&p.stage==='chapel_travel'){p.stage='chapel_echoes';sync()}if(p.stage==='chapel_echoes'&&world.found.every(Boolean)){p.stage='chapel_choice';sync()}if(p.stage==='chapel_ghost'&&world.ghostDefeated){p.stage='chapel_ectoplasm';sync()}if(['chapel_ectoplasm','chapel_return'].includes(p.stage)&&world.ghostDefeated){if(owned('ectoplasm')===0)world.ensureEctoplasm();if(slots.some(i=>i?.id==='ectoplasm')&&p.stage!=='chapel_return'){p.stage='chapel_return';sync()}}}
 function releaseWitness(){if(p.stage!=='chapel_witness'||(p.witnessTopics&7)!==7)return;dismiss();reward(p,'chapel-quest','quest',120);p.stage='kingdom_letter';sound();sync();show('Джон','Бедняга теперь свободен. Значит, ведьма и Лич были не единственными, кто готовил налёты. Передай Альфреду всё, что мы услышали. Одним частоколом от такой беды не укрыться.')}
 function beginRitual(){if(!take('ectoplasm'))return;p.stage='chapel_witness';p.witnessTopics=0;summon();sound();sync();close()}
 function answer(bit,text){p.witnessTopics=(p.witnessTopics||0)|bit;sync();show('Призрак звонаря',text,[['Задать другой вопрос',witnessTalk],['Отойти',close]])}
 function witnessTalk(){if(p.stage!=='chapel_witness')return false;const choices=[['Кто ты? Что с тобой случилось?',()=>answer(1,'Я служил при этой часовне. Пришли люди в тёмных плащах. Велели звонить, когда над лесом загорается их огонь. Я отказался. Они убили меня… но уйти не позволили. Привязали к колоколу. Даже мёртвым я должен был им служить.')],['Что делал этот звон?',()=>answer(2,'Они наложили на колокол заклятие. Кто слышал его и уже носил в себе злобу, становился ещё злее. Звери бросались к домам, а мёртвые выходили из могил. Ведьма гнала стаи из леса. Лич собирал тех, кто погибал.')],['Кто отдавал приказы? Чего они добиваются?',()=>answer(4,'Их имён я не слышал. Но ведьма и хозяин склепа принимали от них приказы. Налёты были только началом. Они говорили, что скоро по дорогам поведут больше людей и что деревня не дождётся помощи из королевства. Я больше ничего не знаю.')],['Как люди здесь живут в вечной ночи?',()=>answer(0,'По часам и привычкам. Трактир открывали после третьей смены караула, на торг ходили с фонарями. Солнца я не видел и при жизни. Старики говорили, что прежде хлеб рос лучше. Мы растили то, что приживалось, и берегли каждую свечу.')],['Что ты знаешь об Ордене?',()=>answer(0,'Иногда через деревню проходили охотники из крепости Ордена. Платили за ночлег, спрашивали о пропавших. Один раз забрали с собой крепкого парня — учить ремеслу. Больше его я не видел. За ворота своей школы посторонних они не пускали. Что там делали, не знаю.')],['А вампиры? Ты видел их?',()=>answer(0,'Я видел человека, который оказался у ворот быстрее, чем стражник успел снять засов. После его ухода пропал возница. Но я не могу поклясться, кем он был. О вампирах говорили всякое: быстры, голодны, боятся солнца. Только где теперь проверить последнее?')]];if((p.witnessTopics&7)===7)choices.push(['Покойся с миром',releaseWitness]);choices.push(['Отойти',close]);show('Призрак звонаря','Я слышу тебя. Спроси, пока голос ещё держится.',choices);return true}
 function talk(){if(p.stage==='chapter_complete'){show('Джон','Ведьма мертва, Лич повержен, а колокол всё ещё звонит. Значит, заклятие осталось в самой часовне. Южная арка за кладбищем ведёт к ней. Сломай три оберега у воды и алтаря, затем останови колокол. И будь осторожен: я не знаю, кто продолжает звонить.',[['Я отправлюсь к часовне',()=>{p.stage='chapel_travel';sound();sync();close()}],['Мне нужно подготовиться',close]]);return true}if(p.stage==='chapel_return'){if(!slots.some(i=>i?.id==='ectoplasm')){p.stage='chapel_ectoplasm';sync();show('Джон','Мне нужны сами останки. Если ты их потерял, осмотри место, где был повержен звонарь, или верни потерянные вещи.');return true}show('Джон','Это эктоплазма. Ещё держит очертания и голос. Я умею возвращать таким останкам форму. Обряд удержит его здесь, пока мы не отпустим. С мёртвыми в моей работе приходится ладить. Попробуем спросить, что удерживало его у колокола.',[['Провести обряд',beginRitual],['Позже',close]]);return true}if(p.stage==='chapel_witness'){show('Джон','Звонарь ждёт рядом. Поговори с ним. Когда узнаешь всё, отпусти его с миром.');return true}if(p.stage==='chapel_done'){world?.startGhost?.();p.stage='chapel_ghost';sync();show('Джон','Колокол умолк, но у входа в часовню появилась беспокойная тень. Узнай, кто остался там. Если придётся сражаться, принеси мне её останки.');return true}if(p.stage.startsWith('kingdom_')){show('Джон','Расскажи Альфреду о звонаре. Если налётчики готовят что-то ещё, нам нужна помощь королевства.');return true}if(p.stage.startsWith('chapel_')){show('Джон',p.stage==='chapel_ghost'?'Разберись с тенью у входа. Её останки могут сохранить голос.':p.stage==='chapel_ectoplasm'?'Подбери останки звонаря. Освободи место в сумке, если нужно.':'Южная арка ведёт к часовне. Сначала три оберега, затем колокол.');return true}return false}
 function stopBell(){if(p.stage!=='chapel_choice'||!world.setChoice('seal'))return;p.stage='chapel_ghost';sync();sound();show('Колокол умолк','Последний узел заклятия лопается. Вы снимаете язык колокола. Со стороны входа тянется белёсый след — там собирается человеческая фигура. Тишина разрывается криком.')}
 function interact(){if(!world)return;if(!world.inside){if(!chapelUnlocked(p))return show('Дорога к часовне','Сначала поговорите с Джоном о звонке после гибели Лича.');world.enter();tick();sync();return}const action=world.action();if(!action)return;if(action.type==='exit'){world.leave();sync();return}if(action.type==='echo'){if(!['chapel_echoes','chapel_choice'].includes(p.stage))return show('Оберег','Оберег уже не держит заклятие.');if(world.collect(action.index)){tick();sync();sound();show('Разрушенный оберег',WARDS[action.index]+'\n\nРазрушено: '+world.found.filter(Boolean).length+' / 3.')}return}if(action.type==='bell'){if(p.stage==='chapel_choice')show('Проклятый колокол','Три оберега сломаны. Осталось снять язык колокола и оборвать последнее крепление заклятия.',[['Остановить колокол',stopBell],['Пока не трогать',close]]);else show('Колокол',world.choice?'Колокол больше не звонит.':'Три оберега держат заклятие. Сначала разрушьте их.')}}
 return {tick,talk,interact,witnessTalk};
}
